/* Community chat, round 39 (run after part 270): a message's delivered state and who is online. `community_conversations` gets `a_delivered_at` and `b_delivered_at`, and `community_chat_group_members` gets `delivered_at`: when each person's own Storelib last had everything sent to them, which turns the sender's one tick into two. `public.community_mark_delivered(community, user)` writes those marks in one call, only where something newer from somebody else is waiting, so the realtime update it causes reaches the sender once; the server calls it after a member's list of conversations is read (server only, never the browser). `public.community_online_topic_ok(topic, write)` decides who may use a member's presence topic `online:<community>:<user>` on realtime: an active member of a live community with chat on may watch another active member's topic, and only that member may say they are here on it; added to realtime.messages for presence when this role may. Nothing is stored for presence. No rows change; until it runs messages show sent and seen as before, and a person's last heartbeat stands in for online. Safe to run again. */
ALTER TABLE public.community_conversations ADD COLUMN IF NOT EXISTS a_delivered_at timestamptz, ADD COLUMN IF NOT EXISTS b_delivered_at timestamptz;
ALTER TABLE public.community_chat_group_members ADD COLUMN IF NOT EXISTS delivered_at timestamptz;
CREATE OR REPLACE FUNCTION public.community_mark_delivered(p_community uuid, p_user uuid) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ DECLARE v_total integer := 0; v_n integer := 0; BEGIN IF p_community IS NULL OR p_user IS NULL THEN RETURN 0; END IF; UPDATE public.community_conversations SET a_delivered_at = now() WHERE community_id = p_community AND user_a = p_user AND last_message_at IS NOT NULL AND last_author_id IS DISTINCT FROM p_user AND (a_delivered_at IS NULL OR a_delivered_at < last_message_at); GET DIAGNOSTICS v_n = ROW_COUNT; v_total := v_total + v_n; UPDATE public.community_conversations SET b_delivered_at = now() WHERE community_id = p_community AND user_b = p_user AND last_message_at IS NOT NULL AND last_author_id IS DISTINCT FROM p_user AND (b_delivered_at IS NULL OR b_delivered_at < last_message_at); GET DIAGNOSTICS v_n = ROW_COUNT; v_total := v_total + v_n; UPDATE public.community_chat_group_members gm SET delivered_at = now() FROM public.community_chat_groups g WHERE g.id = gm.group_id AND gm.community_id = p_community AND gm.user_id = p_user AND g.archived_at IS NULL AND g.last_message_at IS NOT NULL AND g.last_author_id IS DISTINCT FROM p_user AND (gm.delivered_at IS NULL OR gm.delivered_at < g.last_message_at); GET DIAGNOSTICS v_n = ROW_COUNT; RETURN v_total + v_n; END $f$;
CREATE OR REPLACE FUNCTION public.community_online_topic_ok(p_topic text, p_write boolean) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $f$ DECLARE v_community uuid; v_user uuid; BEGIN IF auth.uid() IS NULL OR p_topic IS NULL OR p_topic !~ '^online:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN RETURN false; END IF; v_community := substr(p_topic, 8, 36)::uuid; v_user := substr(p_topic, 45, 36)::uuid; IF p_write AND v_user <> auth.uid() THEN RETURN false; END IF; RETURN EXISTS (SELECT 1 FROM public.communities k WHERE k.id = v_community AND k.deleted_at IS NULL AND k.suspended_at IS NULL AND k.chat_enabled) AND public.community_role_of(v_community, auth.uid()) IS NOT NULL AND public.community_role_of(v_community, v_user) IS NOT NULL; END $f$;
REVOKE ALL ON FUNCTION public.community_mark_delivered(uuid, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.community_mark_delivered(uuid, uuid) TO service_role;
REVOKE ALL ON FUNCTION public.community_online_topic_ok(text, boolean) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.community_online_topic_ok(text, boolean) TO authenticated, service_role;
DO $do$ BEGIN IF to_regclass('realtime.messages') IS NULL OR to_regprocedure('realtime.topic()') IS NULL THEN RAISE NOTICE 'community chat: realtime.messages is not here, online shows the last heartbeat instead.'; RETURN; END IF; BEGIN EXECUTE 'DROP POLICY IF EXISTS "storelib member online read" ON realtime.messages'; EXECUTE 'CREATE POLICY "storelib member online read" ON realtime.messages FOR SELECT TO authenticated USING (realtime.messages.extension = ''presence'' AND public.community_online_topic_ok(realtime.topic(), false))'; EXECUTE 'DROP POLICY IF EXISTS "storelib member online write" ON realtime.messages'; EXECUTE 'CREATE POLICY "storelib member online write" ON realtime.messages FOR INSERT TO authenticated WITH CHECK (realtime.messages.extension = ''presence'' AND public.community_online_topic_ok(realtime.topic(), true))'; EXCEPTION WHEN insufficient_privilege THEN RAISE NOTICE 'community chat: this role may not add policies to realtime.messages, online shows the last heartbeat instead.'; END; END $do$;
notify pgrst, 'reload schema';
